package sqlx_test

import (
	"errors"
	"fmt"
	"testing"

	"github.com/egdaemon/eg/internal/sqlx"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestIgnoreClosed(t *testing.T) {
	t.Run("nil error returns nil", func(t *testing.T) {
		require.Nil(t, sqlx.IgnoreClosed(nil))
	})

	t.Run("closed database error returns nil", func(t *testing.T) {
		require.Nil(t, sqlx.IgnoreClosed(errors.New("sql: database is closed")))
	})

	t.Run("other error is returned unchanged", func(t *testing.T) {
		err := errors.New("some other error")
		require.Same(t, err, sqlx.IgnoreClosed(err))
	})

	t.Run("wrapped closed error is not suppressed", func(t *testing.T) {
		err := fmt.Errorf("outer: %w", errors.New("sql: database is closed"))
		require.Same(t, err, sqlx.IgnoreClosed(err))
	})
}
